const row = $input.first().json;
if (row.status === 'checked_in') {
  return [{json:{ok:true,status:'checked_in',httpStatus:200}}];
}
return [{ json: {
  ok: false, status: row.status || 'invalid_ticket',
  message: row.status === 'already_checked_in' ? 'Ticket has already been checked in.' : 'Ticket not found for this event.',
  httpStatus: row.status === 'already_checked_in' ? 409 : 404
}}];
